head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25600";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25600.onpageload' });
    }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_realsubmInfoList_oncellclick
 * @description grd_realsubmInfoList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_realsubmInfoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_realsubmInfoList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_realsubmInfoList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { await scwin.deleteRow(r["submitprnNm"], r["telNo"], r["submitprnEmail"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_realsubmInfoList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_deleteRow
 * @description delete Row 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_deleteRow = async function () {
    const sbmOptions = {
        id: "tx_fn_deleteRow",
        method: "post",
        action: "/account/realsubmInfo.do",
        ref: "dma_deleteRowReq",
        target: "dlt_realsubmInfoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/account/realsubmInfo.do?method=realsubmInfoList",
        ref: "dma_loadListReq",
        target: "dlt_realsubmInfoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_realsubmInfoList_fillAct
 * @description grd realsubm Info List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_realsubmInfoList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_realsubmInfoList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_realsubmInfoList.fillAct' });
    }
};

/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @param {String} ipt_submitprnNm ipt_submitprnNm
 * @param {*} ipt_telNo ipt_telNo
 * @param {*} ipt_submitprnEmail ipt_submitprnEmail
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRow = async function (ipt_submitprnNm, ipt_telNo, ipt_submitprnEmail) {
    const questionStr = "선택하신 제출인정보(" + ipt_submitprnNm + "/" + ipt_telNo + "/" + ipt_submitprnEmail + ")를 삭제하시겠습니까?";
    if (await $c.win.confirm(questionStr)) {
        const frm = (document.submitInformationForm || { elements: [] });
        frm.action = 'realsubmInfo.do';
        $c.util.getComponent('dma_deleteRowReq').set('method', "deleteRealsubmInfo");
        $c.util.getComponent('ipt_submitprnNm').setValue(ipt_submitprnNm);
        $c.util.getComponent('ipt_telNo').setValue(ipt_telNo);
        $c.util.getComponent('ipt_submitprnEmail').setValue(ipt_submitprnEmail);
        await scwin.tx_fn_deleteRow();
    }
};
